package com.fintrack.khmtomnenh.rfqitem.entity; import com.fasterxml.jackson.annotation.*; import com.fintrack.khmtomnenh.product.entity.Product; import com.fintrack.khmtomnenh.rfq.entity.Rfq; import jakarta.persistence.*; import lombok.*; import java.math.*;
@Entity @Table(name="rfq_items") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class RfqItem {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @JsonBackReference @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="rfq_id") private Rfq rfq; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="product_id") private Product product; @Column(nullable=false) private Integer quantity; @Column(name="target_price",precision=19,scale=2) private BigDecimal targetPrice;}
